function offering(ids,pricingUrl,rows,options={}){
 const plans=rows.split(';').filter(Boolean).map(s=>{const [n,price,note]=s.split('~');return plan(n,price||'Xem tại nguồn',note||'Quyền AI và hạn mức tùy gói.');});
 products(ids,{mode:'managed',groups:[],modelNote:'Model bên trong do nhà cung cấp quản lý. Danh mục lựa chọn model cụ thể chưa được xác nhận từ nguồn đã đối chiếu; không gán thêm tên model theo suy đoán.',plans,pricingUrl,...options});
}
