function getProductProfile(tool){
 const p=PRODUCT_PROFILES[tool.id];
 return {...p,modelUrl:p.modelUrl||tool.url,billingNote:p.billingNote||'Giá theo nguồn tại mốc đối chiếu; thuế, khu vực, kỳ thanh toán và hạn mức có thể khác. Có model trong danh mục không có nghĩa mọi gói đều bao gồm model đó.'};
}
